-- portfolios.user_id is unique. Drop a portfolio whose id is not the photographer id
-- before inserting, so a rerun does not collide with portfolios_user_id_unique.
DELETE FROM portfolios
WHERE (user_id = 2 OR user_id BETWEEN 66 AND 100)
  AND id <> user_id;

